import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"Soundtrack","description":"","frontmatter":{},"headers":[],"relativePath":"demos/SOUNDTRACK.md","filePath":"demos/SOUNDTRACK.md"}'),s={name:"demos/SOUNDTRACK.md"};function o(l,e,h,i,d,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="soundtrack" tabindex="-1">Soundtrack <a class="header-anchor" href="#soundtrack" aria-label="Permalink to &quot;Soundtrack&quot;">​</a></h1><p>The demo songs in the soundtrack style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#angry_shark">Shark Score</a>: <code>angry_shark.yml</code></li><li><a href="#four_wheels_g">Eighties Synth Film Theme</a>: <code>four_wheels_g.yml</code></li><li><a href="#get_the_traps_egon">Spooky Funk Film Theme</a>: <code>get_the_traps_egon.yml</code></li><li><a href="#not_star_trek">Symphonic Space Theme</a>: <code>not_star_trek.yml</code></li><li><a href="#strange_woodworking">Analog-Synth Score</a>: <code>strange_woodworking.yml</code></li><li><a href="#tumbleweeds">Italian Western Theme</a>: <code>tumbleweeds.yml</code></li><li><a href="#very_large_mammals">Boogie-Woogie Film Tune</a>: <code>very_large_mammals.yml</code></li></ul><p><a id="angry_shark"></a></p><h2 id="shark-score-angry-shark-yml" tabindex="-1">Shark Score: <code>angry_shark.yml</code> <a class="header-anchor" href="#shark-score-angry-shark-yml" aria-label="Permalink to &quot;Shark Score: `angry_shark.yml`&quot;">​</a></h2><p>A menacing orchestral film score in the manner of Jaws (John Williams), a low figure speeding up as the shark comes. A creeping cell of three low notes in the basses, first in slow notes with silences, then in eighths as each scene is faster; a tuba, horn calls and timpani; a chase on i VI iv V; a calm stretch of harp and strings before it comes back.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/angry_shark.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/angry_shark.yml</code></a> · D minor · 70 BPM · 3:04 · 9 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/ARPEGGIATOR">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="four_wheels_g"></a></p><h2 id="eighties-synth-film-theme-four-wheels-g-yml" tabindex="-1">Eighties Synth Film Theme: <code>four_wheels_g.yml</code> <a class="header-anchor" href="#eighties-synth-film-theme-four-wheels-g-yml" aria-label="Permalink to &quot;Eighties Synth Film Theme: `four_wheels_g.yml`&quot;">​</a></h2><p>A mid-eighties synth film theme in the manner of Axel F (Harold Faltermeyer), with a hook of its own. The hook starts alone on a saw lead, short notes with gaps, then the drum machine, a sixteenth- note synth bass and synth brass stabs come in one at a time; i for two bars, then VI and VII; a second part on a marimba and a slow theme on bells.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/four_wheels_g.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/four_wheels_g.yml</code></a> · D minor · 117 BPM · 3:01 · 10 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="get_the_traps_egon"></a></p><h2 id="spooky-funk-film-theme-get-the-traps-egon-yml" tabindex="-1">Spooky Funk Film Theme: <code>get_the_traps_egon.yml</code> <a class="header-anchor" href="#spooky-funk-film-theme-get-the-traps-egon-yml" aria-label="Permalink to &quot;Spooky Funk Film Theme: `get_the_traps_egon.yml`&quot;">​</a></h2><p>A mid-eighties spooky funk-pop film theme in the manner of Ghostbusters (Ray Parker Jr.), with a riff of its own. Every bar goes I for two beats, then bVII and IV for one each: synth brass hits and a muted funk guitar on the chords, a synth bass riff, a line that a shout answers, a middle on IV and V, and ghostly whistles over the drums.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/get_the_traps_egon.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/get_the_traps_egon.yml</code></a> · G mixolydian · 116 BPM · 3:02 · 11 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="not_star_trek"></a></p><h2 id="symphonic-space-theme-not-star-trek-yml" tabindex="-1">Symphonic Space Theme: <code>not_star_trek.yml</code> <a class="header-anchor" href="#symphonic-space-theme-not-star-trek-yml" aria-label="Permalink to &quot;Symphonic Space Theme: `not_star_trek.yml`&quot;">​</a></h2><p>A majestic symphonic space-opera theme in the manner of the original Battlestar Galactica (Stu Phillips), with a fanfare of its own. A trumpet fanfare in dotted rhythms and leaps over brass chords, timpani and a marching snare, turning through the borrowed chords bVI and bVII back to I; a lyrical second theme on the strings; a bridge on the horns.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/not_star_trek.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/not_star_trek.yml</code></a> · D major · 106 BPM · 3:01 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="strange_woodworking"></a></p><h2 id="analog-synth-score-strange-woodworking-yml" tabindex="-1">Analog-Synth Score: <code>strange_woodworking.yml</code> <a class="header-anchor" href="#analog-synth-score-strange-woodworking-yml" aria-label="Permalink to &quot;Analog-Synth Score: `strange_woodworking.yml`&quot;">​</a></h2><p>A dark analog-synth score in the manner of Survive and John Carpenter, built on an arpeggiated sequence. One chord arpeggiated in sixteenths runs through everything, barely changing; a pulsing bass on one note, a slow pad, a heartbeat kick and a plain theme in long notes on i VI iv v.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/strange_woodworking.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/strange_woodworking.yml</code></a> · E minor · 84 BPM · 3:03 · 7 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">shapes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/ARPEGGIATOR">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/SWELL">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="tumbleweeds"></a></p><h2 id="italian-western-theme-tumbleweeds-yml" tabindex="-1">Italian Western Theme: <code>tumbleweeds.yml</code> <a class="header-anchor" href="#italian-western-theme-tumbleweeds-yml" aria-label="Permalink to &quot;Italian Western Theme: `tumbleweeds.yml`&quot;">​</a></h2><p>An Italian western film theme of the sixties in the manner of the theme of The Good, the Bad and the Ugly (Ennio Morricone), with a tune of its own. Galloping tom-toms; an ocarina calls and men&#39;s voices answer; a twanging guitar plays the theme on i and a major IV; a trumpet climbs over choir and strings; a harmonica alone with a bell in the middle.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/tumbleweeds.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/tumbleweeds.yml</code></a> · E minor · 112 BPM · 3:00 · 10 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table><p><a id="very_large_mammals"></a></p><h2 id="boogie-woogie-film-tune-very-large-mammals-yml" tabindex="-1">Boogie-Woogie Film Tune: <code>very_large_mammals.yml</code> <a class="header-anchor" href="#boogie-woogie-film-tune-very-large-mammals-yml" aria-label="Permalink to &quot;Boogie-Woogie Film Tune: `very_large_mammals.yml`&quot;">​</a></h2><p>A lumbering boogie-woogie film tune in the manner of Baby Elephant Walk (Henry Mancini), with a tune of its own. A twelve-bar blues: a boogie bass doubled by a tuba, so that it lumbers, an organ on the offbeats, a comic tune high on a calliope that leaves gaps, and brass answering in the gaps.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/soundtrack/very_large_mammals.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/soundtrack/very_large_mammals.yml</code></a> · G major · 112 BPM · 3:00 · 7 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../GROOVES">✓</a></td><td style="text-align:center;"><a href="./../generators/PROGRESSION">✓</a></td></tr></tbody></table>',38)])])}const y=t(s,[["render",o]]);export{g as __pageData,y as default};
